// Monument stories for South batch6.
{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"rameswaram\": [{\"title\": \"Ramanathaswamy: the story of Rama and Sita\", \"text\": \"In Hindu tradition, Rama wished to worship Shiva after defeating Ravana. When Hanuman was delayed bringing a lingam, Sita made one from sand so that Rama could pray. This is the sacred origin story of Ramalingam, not a documented construction record for the present temple.\", \"url\": \"https://www.tamilnadutourism.tn.gov.in/destinations/rameswaram-temple\", \"kind\": \"Hindu tradition, not documented building history\"}], \"kanyakumari\": [{\"title\": \"Gandhi Memorial: remembering the ashes before immersion\", \"text\": \"An urn holding Gandhi's ashes was placed here for people to pay their respects before the ashes were immersed in the sea in 1948. The memorial, completed in 1956, marks that moment of farewell rather than a place where Gandhi lived.\", \"url\": \"https://kanniyakumari.nic.in/tourist-place/mahatma-gandhi/\", \"kind\": \"Documented memorial history\"}], \"puducherry\": [{\"title\": \"French War Memorial: names behind a seafront monument\", \"text\": \"The memorial honours soldiers from French India who died in the First World War. Inaugurated in 1938, it places the human cost of war on the seafront. It is a memorial to the dead, not a palace or a triumphal gateway.\", \"url\": \"https://www.incredibleindia.gov.in/en/puducherry/puducherry/french-war-memorial\", \"kind\": \"Documented memorial history\"}], \"thanjavur\": [{\"title\": \"Brihadisvara: Rajaraja makes a royal statement\", \"text\": \"Rajaraja I commissioned the great Shiva temple at Thanjavur in the early 11th century. Its commanding tower expressed Chola royal ambition as well as devotion. UNESCO calls these living temples because worship traditions continue, not because they are only preserved ruins.\", \"url\": \"https://whc.unesco.org/en/list/250/\", \"kind\": \"Documented patronage and living worship\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

// East batch7 sourced monument stories.
{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"bhubaneswar\": [{\"title\": \"Dhauli: a ruler speaking to officers and the public\", \"kind\": \"Documented inscriptions; not a romantic legend\", \"text\": \"At Dhauli, Ashoka's third-century BCE edicts were cut into rock for the public and the king's officers. The inscriptions turn a royal voice into something people could encounter along a travelled route. They are not the same monument as the much later white Peace Pagoda on the hill.\", \"url\": \"https://asi.nic.in/admin/whatsnew/download/493\"}], \"konark\": [{\"title\": \"Konark: a king gives the Sun a stone chariot\", \"kind\": \"Documented patronage and religious design\", \"text\": \"King Narasimhadeva I commissioned the Sun Temple in the 13th century. Rather than an ordinary shrine, its builders imagined the vehicle of Surya: twelve pairs of stone wheels drawn by seven horses. The chariot turns devotion into an enormous carved journey across the sky. Stories of its master builder and his son are legends, not a verified construction diary.\", \"url\": \"https://whc.unesco.org/en/list/246/\"}], \"gopalpur\": [{\"title\": \"Gopalpur Lighthouse: a light for people at sea\", \"kind\": \"Documented maritime purpose\", \"text\": \"In 1871, the British administration commissioned a beacon on Gopalpur beach: a wick lamp raised on a steel mast. Storm-warning signals were also hoisted there. The light began as practical help for people at sea, not as a decorative lookout. The lighthouse facilities changed over time, so the present tower should not be called the original 1871 mast.\", \"url\": \"https://www.dgll.nic.in/DGLL-light-house-location/about-kolkata/gopalpur-lighthouse\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

// Explicit map coverage note for new guides without projected pins.
{let h=fs.readFileSync("private-assets/index.html","utf8");h=h.replace("<title id=\"indiaMapTitle\">Map of India with destination markers</title>","<title id=\"indiaMapTitle\">Map of India with selected destination markers</title>");h=h.replace("<div class=\"map-wrap\"", "<p class=\"muted\">Map pins cover selected destinations. The new Odisha, Northeast and Gujarat guides are available in the destination list and search; their map pins have not been added.</p><div class=\"map-wrap\"");fs.writeFileSync("private-assets/index.html",h);}

// Northeast batch8 sourced monument stories.
{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"gangtok\": [{\"title\": \"Enchey: prayer wheels on the way to worship\", \"kind\": \"Documented living religious practice\", \"text\": \"The approach to Enchey Monastery includes a path lined with prayer wheels. The monastery also holds Cham ritual dance observances on the Tibetan lunar calendar. Its human story is still being lived by worshippers: a visitor enters a religious community, not a stage set with a guaranteed daily show.\", \"url\": \"https://gangtokdistrict.nic.in/signature-attractions/\"}], \"guwahati\": [{\"title\": \"Umananda: Shiva, Uma and an island name\", \"kind\": \"Religious legend, not documented construction history\", \"text\": \"Assam Tourism records a tradition that Shiva is present here to enhance the love of Uma, giving the island temple its name, Umananda. Another tradition links the island to Shiva burning Kamdev to ashes. These are sacred stories told about the place, not verified events or a date for building the present temple.\", \"url\": \"https://assamtourism.gov.in/umananda-temple.php\"}], \"tawang\": [{\"title\": \"Tawang Monastery: a community above the valley\", \"kind\": \"Documented founding and living Buddhist tradition\", \"text\": \"Merak Lama Lodre Gyamtso founded Tawang Monastery in 1680-81, overlooking the Tawang Chu valley. Its story continues through the Monpa community's monastery festivals, including Torgya. The buildings are more than a viewpoint: they remain a place of religious life, where visitors follow the community's rules.\", \"url\": \"https://tawang.nic.in/tourism/tourist-places/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

// West batch9 sourced monument stories.
{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"dwarka\": [{\"title\": \"Rukmini: the story of a separate shrine\", \"kind\": \"Religious legend, not a verified historical event\", \"text\": \"A tradition recorded by Gujarat Tourism tells of Krishna and Rukmini pulling the sage Durvasa's chariot. Thirsty Rukmini drank water before offering it to the sage, who cursed her to live apart from Krishna. The story explains why her shrine stands separately from Dwarkadhish Temple; it is a sacred explanation, not a construction record.\", \"url\": \"https://gujarattourism.com/saurashtra/devbhoomi-dwarka/rukmini-temple.html\"}], \"somnath\": [{\"title\": \"Somnath: rebuilding across several decades\", \"kind\": \"Documented modern reconstruction, separate from sacred origin traditions\", \"text\": \"The present temple grew from a reconstruction effort supported by Sardar Patel after Independence. The trust records a foundation ceremony in 1950 and consecration by President Rajendra Prasad on 11 May 1951. Work continued in stages, so 1951 is a consecration milestone, not proof that every part of today's complex was finished that year.\", \"url\": \"https://somnath.org/sts23/introduction\"}], \"bhuj\": [{\"title\": \"Aina Mahal: a ruler meets a traveller's skills\", \"kind\": \"Documented patronage and craft exchange\", \"text\": \"Maharao Lakhpatji commissioned Aina Mahal in the 18th century, working with Ram Singh Malam, a sailor from Dwarka who had learned European arts and crafts on his travels. Mirrors, tiles and glass turned that meeting of patron and maker into a palace interior. The tale that the ruler auctioned his bed every year is a legend, not a fact needed to understand the building.\", \"url\": \"https://gujarattourism.com/kutch-zone/kutch/aina-mahal.html\"}], \"ektanagar\": [{\"title\": \"Statue of Unity: a monument to Patel\", \"kind\": \"Documented commemorative purpose\", \"text\": \"Inaugurated on 31 October 2018, the 182-metre Statue of Unity honours Sardar Vallabhbhai Patel and his role in bringing princely states into independent India. Its museum and projection show tell that public story. The monument was built long after Patel's lifetime; it is a commemoration, not a place where he lived.\", \"url\": \"https://www.gujarattourism.com/central-zone/narmada/statue-of-unity.html\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"ujjain\": [{\"title\": \"Mahakaleshwar: sacred time in Ujjain\", \"kind\": \"Religious belief and literary tradition\", \"text\": \"Ujjain's district administration describes Mahakaleshwar as one of the twelve Jyotirlingas and links Mahakala with the city's old role in reckoning time. Devotees believe the lingam is swayambhu, or self-manifested. These are sacred traditions, not a scientifically dated account of how the shrine began. The present complex and its rituals have their own changing history.\", \"url\": \"https://ujjain.nic.in/en/tourist-place/shri-mahakaleshwar-temple/\"}], \"sanchi\": [{\"title\": \"The Great Stupa: built in layers\", \"kind\": \"Documented multi-century building history\", \"text\": \"Sanchi's Great Stupa was not built all at once. UNESCO traces its beginning to a brick stupa in Ashoka's third-century-BCE reign, followed by enlargement, a stone covering and later carved gateways. Its artists often represented the Buddha through symbols and stories rather than a standing portrait. Later shrines added more layers: the monument records generations of patrons, worshippers and makers.\", \"url\": \"https://whc.unesco.org/en/list/524/\"}], \"mandu\": [{\"title\": \"Jahaz Mahal: a ship made of stone\", \"kind\": \"Documented setting and architectural name\", \"text\": \"Jahaz Mahal stands on a narrow strip between Munj Talao and Kapur Talao. Reflections make its long, low form resemble a ship at anchor, giving the palace its name. Madhya Pradesh Tourism associates it with Sultan Ghiyasuddin Khilji. The surrounding reservoirs and buildings are part of Mandu's designed landscape, not evidence that this stone ship ever sailed.\", \"url\": \"https://www.mptourism.com/jahaz-mahal-a-must-visit-palace-in-mandu-madhya-pradesh.html\"}], \"maheshwar\": [{\"title\": \"Maheshwar: Ahilyabai's town of worship and weaving\", \"kind\": \"Documented royal patronage and continuing craft\", \"text\": \"Ahilyabai Holkar made Maheshwar her seat of rule and supported its temples and weaving tradition. The riverside fort and ghats give that patronage a visible setting, while Maheshwari textiles carry the craft into living workshops. This is a continuing community of makers, not a claim that one ruler personally invented every pattern or that every sari sold nearby is handwoven.\", \"url\": \"https://www.mptourism.com/maheshwar-tourist-places-and-maheshwari-saris.html\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"patna\": [{\"title\": \"Golghar: a granary after famine\", \"kind\": \"Documented colonial construction\", \"text\": \"Captain John Garstin built Golghar in 1786 after the devastating 1770 famine. Its great dome and winding exterior stairways were designed around storing and moving grain, rather than as a royal tomb or temple. The granary's striking shape now makes it a Patna landmark. Current stair access is a separate safety and visitor-management question, not guaranteed by its history.\", \"url\": \"https://tourism.bihar.gov.in/en/destinations/patna/gol-ghar\"}], \"rajgir\": [{\"title\": \"Venuvan: a king's gift in Buddhist tradition\", \"kind\": \"Buddhist tradition recorded by Bihar Tourism\", \"text\": \"Buddhist tradition associates Venuvan, the Bamboo Grove, with King Bimbisara's gift to the Buddha and his community. The story makes a quiet garden part of Rajgir's sacred landscape, showing how royal support could create a place for teaching and residence. Today's garden and sculptures should not be mistaken for an unchanged sixth-century-BCE monastery.\", \"url\": \"https://tourism.bihar.gov.in/en/destinations/nalanda/venuvan\"}], \"nalanda\": [{\"title\": \"Nalanda: learning built over generations\", \"kind\": \"Documented monastic and scholastic history\", \"text\": \"Nalanda was a Buddhist monastic and learning institution with teaching, residential and sacred spaces, not a single classroom building. UNESCO describes its long institutional life from the fifth to thirteenth centuries CE and the influence of its methods across Asia. Its stupas, shrines and monasteries grew in stages. The modern Nalanda University is a separate institution, not the excavated ruins reopened unchanged.\", \"url\": \"https://whc.unesco.org/en/list/1502/\"}], \"vaishali\": [{\"title\": \"Vaishali's peace pagoda: a modern shared project\", \"kind\": \"Documented modern patronage, separate from ancient relic traditions\", \"text\": \"Vaishali's Vishwa Shanti Stupa belongs to a modern peace-pagoda movement inspired by Nichidatsu Fuji after the atomic bombings in Japan. Bihar Tourism credits Nipponzan Myohoji and the Rajgir Buddha Vihar Society, supported by devotees in India and Japan. Its relic associations are religious tradition; the white pagoda itself is not an Ashokan-age building or Rajgir's ropeway-served hilltop stupa.\", \"url\": \"https://tourism.bihar.gov.in/en/destinations/vaishali/vishwa-shanti-stupa\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"nashik\": [{\"title\": \"Kalaram Temple: worship and the fight for entry\", \"kind\": \"Documented social history, separate from Ramayana traditions\", \"text\": \"Nashik's Kalaram Temple is a place of worship and a landmark in the struggle against caste exclusion. Maharashtra Tourism records that B.R. Ambedkar led the 1930 temple-entry satyagraha to challenge the denial of entry to Dalits. The episode is part of the temple's modern social history; the Ramayana associations of Panchvati belong to a separate sacred tradition.\", \"url\": \"https://maharashtratourism.gov.in/districts/nashik/\"}], \"sambhajinagar\": [{\"title\": \"Bibi Ka Maqbara: remembering Dilras Banu Begum\", \"kind\": \"Documented memorial subject; disputed patronage acknowledged\", \"text\": \"Bibi Ka Maqbara commemorates Dilras Banu Begum, Aurangzeb's wife. Sources disagree about whether the original commission should be credited to Aurangzeb or their son Azam Shah. Rather than turn that dispute into a neat father-or-son story, the guide keeps the secure memorial subject and acknowledges the debate. Its Deccan setting, gardens and materials deserve attention beyond comparisons with the Taj Mahal.\", \"url\": \"https://www.sahapedia.org/bibi-ka-maqbara-overview\"}], \"ajanta\": [{\"title\": \"Ajanta: two great phases of Buddhist art\", \"kind\": \"Documented multi-period monastic history\", \"text\": \"Ajanta was not carved and painted in one campaign. UNESCO describes an early group of Buddhist caves from the second and first centuries BCE, followed by richly decorated caves added in the Gupta period, in the fifth and sixth centuries CE. Monks, patrons, painters and sculptors shaped a place of residence and worship whose images tell religious stories. The paintings are fragile heritage, not surfaces to touch or light for a better photograph.\", \"url\": \"https://whc.unesco.org/en/list/242/\"}], \"ellora\": [{\"title\": \"Kailasa: a temple cut from the hill\", \"kind\": \"Documented rock-cut construction and attributed patronage\", \"text\": \"Kailasa, Ellora's Cave 16, was excavated from the rock rather than assembled like a conventional masonry temple. ASI attributes this great Hindu monument to Rashtrakuta ruler Krishna I. It stands within a much wider complex of Buddhist, Hindu and Jain caves created over generations. One ruler's association with Kailasa does not make him the builder of every Ellora cave, and no reliable construction duration is promised here.\", \"url\": \"https://asi.nic.in/pages/WorldHeritageElloraCaves\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"badami\": [{\"title\": \"Badami: faiths carved into sandstone\", \"kind\": \"Documented Hindu and Jain cave heritage\", \"text\": \"Badami's four principal cave temples do not tell a single-faith story. The first three display Hindu deities, including Shiva as Nataraja and Vishnu in different forms; the fourth is Jain, with Tirthankara imagery. These rock-cut interiors belong to the wider early Chalukya landscape. Pattadakal is the inscribed UNESCO site; Badami's association with it does not make every monument here independently World Heritage-listed.\", \"url\": \"https://karnatakatourism.org/en/destinations/badami\"}], \"aihole\": [{\"title\": \"Durga Temple: a name and an architectural experiment\", \"kind\": \"District explanation of the name, not a goddess-dedication claim\", \"text\": \"The Bagalkote district guide links the name Durga to Durgadagudi, a temple near a fort. The name alone is not evidence that the shrine was dedicated to goddess Durga. Its rounded, apsidal end and surrounding colonnade make it one of Aihole's most recognisable experiments in temple form. Elsewhere in the village, rock-cut Shiva imagery and the Jain Meguti monument show why Aihole needs more than a single-temple photograph.\", \"url\": \"https://bagalkot.nic.in/en/tourist-place/aihole/\"}], \"pattadakal\": [{\"title\": \"Virupaksha: a queen's commission\", \"kind\": \"UNESCO attribution; conflicting ASI wording noted\", \"text\": \"UNESCO identifies Queen Lokamahadevi as the patron of Virupaksha Temple, built around 740 to commemorate her husband's victory over southern rulers. Its architecture belongs to Pattadakal's meeting of northern and southern temple forms. An ASI overview confusingly extends the attribution for Mallikarjuna's queen to Virupaksha; this guide follows UNESCO's explicit Lokamahadevi attribution rather than merging the queens into one person.\", \"url\": \"https://whc.unesco.org/en/list/239/\"}], \"vijayapura\": [{\"title\": \"Gol Gumbaz: memory beneath the great dome\", \"kind\": \"Documented mausoleum, distinct from acoustic superlatives\", \"text\": \"Gol Gumbaz was built as the mausoleum of Muhammad Adil Shah, a ruler of the Adil Shahi dynasty. The district guide distinguishes the visible memorial tombs from the actual burials in a crypt below. The dome's gallery is famous for its acoustics, but sources give conflicting echo counts and global size rankings, so this story promises neither. Ibrahim Rauza commemorates a different ruler and should not be folded into the same tomb narrative.\", \"url\": \"https://vijayapura.nic.in/en/places-of-interest/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"jodhpur\": [{\"title\": \"Mehrangarh: a fort built over generations\", \"kind\": \"Museum-trust history, separate from solar ancestry tradition\", \"text\": \"Rao Jodha began a new fortified seat on an isolated rock south of Mandore, and the town below took his name. Mehrangarh's museum trust describes a complex that grew under successive rulers, serving as defence, royal residence, a place of worship and a centre of artistic patronage. Its name, fort of the sun, refers to the Rathores' mythical descent from Surya. That ancestry belongs to dynastic tradition, not a documented family tree back to a deity.\", \"url\": \"https://www.mehrangarh.org/mehrangarh-2/history/\"}], \"bikaner\": [{\"title\": \"Junagarh: more than one ruler's palace\", \"kind\": \"Documented patronage; precise chronology kept cautious\", \"text\": \"Junagarh's great late-sixteenth-century building phase is associated with Raja Rai Singh, while later rulers added palaces, halls and collections. It is a layered royal complex rather than one finished design frozen on a single date. Official tourism accounts differ in their precise construction chronology and in claims that it was never captured, so this guide does not repeat either as settled fact. The Bikaner fort is also distinct from Junagadh city in Gujarat.\", \"url\": \"https://www.incredibleindia.gov.in/en/rajasthan/bikaner/junagarh-fort\"}], \"pushkar\": [{\"title\": \"Pushkar Lake: the lotus story\", \"kind\": \"Hindu sacred legend, not scientific or medical fact\", \"text\": \"A Hindu tradition links Pushkar Lake to a lotus dropped by Brahma. It gives the lake and surrounding pilgrimage town their sacred meaning for devotees, but it is not a scientific explanation of the lake's formation. Brahma Temple is one of the best-known shrines dedicated to the creator deity, not the only such temple in the world. Beliefs about ritual bathing must not be read as promises to cure disease or as proof that entering the water is safe.\", \"url\": \"https://www.tourism.rajasthan.gov.in/content/rajasthan-tourism/en/tourist-destinations/pushkar-lake.html\"}], \"bundi\": [{\"title\": \"Bundi's palace: walls that hold paintings\", \"kind\": \"Documented multi-period palace and painting heritage\", \"text\": \"Garh Palace is a group of buildings shaped by successive rulers, not one palace completed in a single campaign. Its painted rooms and Chitrashala connect it with the Bundi school of art, known for courtly and devotional scenes, landscapes and expressive figures. These paintings remain part of the historic building, not souvenirs to touch or fragments to take away. Room access and photography rules can differ, so the surviving art is best viewed under current staff directions.\", \"url\": \"https://www.tourism.rajasthan.gov.in/bundi.html\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"chandigarh\": [{\"title\": \"Rock Garden: a second life for discarded things\", \"kind\": \"Documented artistic practice, separate from Capitol UNESCO status\", \"text\": \"Nek Chand made the Rock Garden's figures and settings from discarded materials including broken bangles, ceramics, tiles and bottles. The city tourism guide describes a mixture of landscape, architecture and sculpture built through personal experimentation. Its creative reuse is the story here. The Rock Garden should not be called part of the UNESCO-listed Le Corbusier Capitol Complex merely because both are in Chandigarh.\", \"url\": \"https://chandigarhtourism.gov.in/pages/page/rock-garden\"}], \"patiala\": [{\"title\": \"Qila Mubarak: a fort that changed with its rulers\", \"kind\": \"Documented layered history; conflicting rebuilding attribution kept cautious\", \"text\": \"Qila Mubarak began as a mud fort and developed into a palace-fort complex under Patiala's rulers. District history distinguishes the inner Qila Androon from later outer buildings and Darbar Hall. Accounts differ on who should receive credit for particular rebuilding phases, so the whole complex is not assigned to one builder or one construction span. Its murals and collections require current access checks and careful treatment, not the assumption that every old palace room is open.\", \"url\": \"https://patiala.nic.in/architecture/\"}], \"anandpur\": [{\"title\": \"Kesgarh Sahib and the formation of the Khalsa\", \"kind\": \"Documented Sikh historical and religious significance\", \"text\": \"The Rupnagar district account identifies Kesgarh Sahib with the place where Guru Gobind Singh founded the Khalsa at Vaisakhi in 1699 and initiated the Panj Piare. It is one of Sikhism's five Takhts, not simply a viewpoint above the town. For visitors, that living religious significance matters as much as the building: worshippers' privacy, respectful dress and the shrine's current code come before photography or sightseeing.\", \"url\": \"https://rupnagar.nic.in/tourist-place/sri-keshgarh-sahib-sri-anandpur-sahib/\"}], \"kapurthala\": [{\"title\": \"Moorish Mosque: a commission across traditions\", \"kind\": \"District-recorded patronage and architectural influence\", \"text\": \"Kapurthala's district guide credits Maharaja Jagatjit Singh with commissioning the Moorish Mosque and records its completion in 1930. Its design drew on the Qutbia mosque at Marrakesh, while the city overview notes work by students of Lahore's Mayo School of Arts. The mosque expresses a particular princely patronage and architectural exchange, not a generic palace fa\\u00e7ade. As a religious place, it deserves current worship and access checks rather than assumed unrestricted entry.\", \"url\": \"https://kapurthala.gov.in/tourist-place/dhauli-8/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"dharamshala\": [{\"title\": \"St John in the Wilderness: a church in the cedar woods\", \"kind\": \"Documented colonial-era Christian heritage\", \"text\": \"Himachal Tourism dates St John in the Wilderness to 1852 and describes its neo-Gothic stone architecture and stained glass. The church survived the 1905 Kangra earthquake that damaged much of the region. Its grounds include the grave of Lord Elgin. This is a living Christian site within a town better known today for Tibetan Buddhist institutions; neither identity should erase the other, and worship and grounds access still need respect.\", \"url\": \"https://himachaltourism.gov.in/destination/dharamshala/\"}], \"dalhousie\": [{\"title\": \"Dalhousie: a colonial hill settlement, not a healing promise\", \"kind\": \"Documented colonial setting; exact founding year kept cautious\", \"text\": \"Dalhousie developed as a British hill settlement across several wooded ridges in the mid-nineteenth century. Its name recalls Lord Dalhousie, while churches and old streets preserve parts of that colonial history. Tourism descriptions differ on an exact founding year, so no single-year origin is forced here. Accounts of Subhas Chandra Bose staying in 1937 explain local place names, not a promise that the town's air or spring water cures illness.\", \"url\": \"https://himachaltourism.gov.in/destination/dalhousie/\"}], \"chamba\": [{\"title\": \"Bhuri Singh Museum: preserving Chamba's own history\", \"kind\": \"Museum-recorded foundation and collection history\", \"text\": \"The Bhuri Singh Museum says it was founded in 1908 to collect and preserve Chamba's cultural heritage. Raja Bhuri Singh donated his inherited art collection, while scholar J.Ph.Vogel helped set up the institution. Its paintings, inscriptions, craft and other objects tell the region's history through surviving evidence. The museum is not simply another palace interior, and current opening and photography rules are separate from visits to the town's living temples.\", \"url\": \"https://www.bhurisinghmuseumchamba.in/about-us/\"}], \"kullu\": [{\"title\": \"Raghunath Temple and a valley's gathering\", \"kind\": \"Documented royal patronage, with penance story labelled legend\", \"text\": \"Raghunath Temple is associated with Raja Jagat Singh and seventeenth-century Kullu. The story that he established it as penance belongs to the temple's sacred tradition. Its continuing role in Kullu Dussehra connects royal history, living devotion and the gathering of valley deities. A historical account is not a guarantee that a visitor can enter every ritual space, see a particular procession or use the festival grounds without current directions.\", \"url\": \"https://www.incredibleindia.gov.in/en/himachal-pradesh/kullu/raghunathji-temple\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"nainital\": [{\"title\": \"St John in the Wilderness: memory beyond the lake\", \"kind\": \"Documented memorial history; early construction dates kept cautious\", \"text\": \"St John in the Wilderness at Mallital carries memorials to people who died in Nainital's 1880 landslide. Independent reporting records the community returning to remember that disaster. Accounts give different dates for the church's selection, foundation and first services, so no single opening year is forced here. The memorial makes this living Christian site part of the town's history of loss, not merely a scenic stop beside a holiday lake.\", \"url\": \"https://www.nainital.info/attractions/st-john-in-the-wilderness-church-nainital-india/\"}], \"almora\": [{\"title\": \"Almora: a ridge town shaped by the Chand rulers\", \"kind\": \"Documented dynasty and administrative history\", \"text\": \"The Almora district history associates the town's development with Kalyan Chand and the Chand dynasty, and records the older name Rajapur. Later Gorkha and British administration changed the wider region. The town's old market lanes and living Nanda Devi shrine sit within that layered Kumaoni setting. A broad historical link does not establish the age of every visible shopfront or temple wall; these are surviving, changing places rather than an untouched royal town.\", \"url\": \"https://almora.nic.in/history/\"}], \"ranikhet\": [{\"title\": \"Jhoola Devi: bells as a living devotional practice\", \"kind\": \"Local sacred tradition, not a verified supernatural claim\", \"text\": \"The district account describes Jhoola Devi as a form of Durga seated on a cradle, which gives the shrine its name. Devotees offer bells in thanks for wishes they believe have been fulfilled. The account's great age for the shrine is explicitly local tradition, not a dated construction record. Visiting means entering an active place of worship: the bells carry people's faith, but neither a visit nor an offering promises an outcome.\", \"url\": \"https://almora.nic.in/tourist-place/jhoola-devi-temple-ranikhet/\"}], \"kausani\": [{\"title\": \"Kausani: Gandhi's quiet work on the Gita\", \"kind\": \"Documented stay and writing history, not a new scripture claim\", \"text\": \"The Gandhi Heritage Portal records Gandhi's stay in Kausani from 22 June to 2 July 1929 and cites his letters about setting other work aside for the Gita. It describes revision and completion of his preface, rather than claiming he composed the scripture here. The site is remembered through Anasakti Ashram. That history is distinct from Lakshmi Ashram and from current accommodation, prayer or visitor arrangements, which need their own permission and checks.\", \"url\": \"https://www.gandhiheritageportal.org/gandhi_heritage_site/writeup/Ng%3D%3D\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"visakhapatnam\": [{\"title\": \"INS Kurusura: from naval service to a shore museum\", \"kind\": \"Documented naval and museum history\", \"text\": \"VMRDA records that INS Kurusura entered Indian naval service in 1969 and was decommissioned in 2001 after 31 years. The submarine was brought ashore onto a concrete foundation at RK Beach Road and opened as a museum in 2002. What visitors see is a preserved vessel with a real working history, not a replica or permission to enter active naval facilities. Museum opening, tickets and the confined interior need separate checks.\", \"url\": \"https://vmrda.ap.gov.in/visiting-places/submarine-museum\"}], \"vijayawada\": [{\"title\": \"Undavalli: a separate rock-cut heritage visit\", \"kind\": \"Documented architecture; early-use claims kept cautious\", \"text\": \"Undavalli Caves lie across the Krishna from Vijayawada in the Guntur region. Their rock-cut chambers and the reclining Vishnu figure are part of the area's layered religious and architectural heritage. Accounts of early phases and changing religious use need more care than a single-builder story, so no one-year origin is forced here. The monument is a separate road excursion, not a room inside Kanaka Durga Temple or a guaranteed boat stop.\", \"url\": \"https://www.incredibleindia.gov.in/en/andhra-pradesh/guntur/undavalli-caves\"}], \"amaravati\": [{\"title\": \"Amaravati Mahachaitya: read the remains, not an intact dome\", \"kind\": \"Documented Buddhist archaeological heritage\", \"text\": \"Amaravati's Mahachaitya grew through ancient phases and became known for carved limestone panels with Buddhist narratives and decorative motifs. Its surviving remains and museum objects should be read together: the original monument is not intact, and important sculptures are now dispersed among collections. The old Amaravathi archaeological town is also distinct from the wider modern capital project. Sacred traditions about the site do not establish a single construction date or a promise of current ritual access.\", \"url\": \"https://www.incredibleindia.gov.in/en/andhra-pradesh/amaravati/amaravati-mahachaitya\"}], \"lepakshi\": [{\"title\": \"Lepakshi: Vijayanagara painting and a living shrine\", \"kind\": \"Inscription and architectural history; UNESCO tentative status only\", \"text\": \"India's UNESCO Tentative List submission describes major Veerabhadra Temple development during the Vijayanagara period and inscriptions from Achyutaraya's reign. Murals illustrate epic and devotional stories, while the separate Nandi and Naga-linga show large-scale stone carving. Local Jatayu and place-name stories belong to sacred tradition rather than a proven account of construction. Tentative listing is not World Heritage inscription; current shrine and conservation directions still govern the visit.\", \"url\": \"https://whc.unesco.org/en/tentativelists/6607\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"warangal\": [{\"title\": \"Warangal's carved gateways: a Kakatiya capital in fragments\", \"kind\": \"Documented fort heritage; UNESCO scope kept separate\", \"text\": \"The district account places Warangal Fort's major development in the Kakatiya period and describes its carved stone gateways. Surviving fragments show the work of a capital whose buildings changed and suffered over time; not every structure now seen belongs to one ruler or one building phase. The gateways are not a complete standing palace. Ramappa's separate UNESCO inscription at Palampet should not be widened into an inscription for the whole city.\", \"url\": \"https://warangal.telangana.gov.in/tourist-place/warangal-fort/\"}], \"ramappa\": [{\"title\": \"Ramappa: stone carving and a lighter roof\", \"kind\": \"UNESCO-documented architecture and construction history\", \"text\": \"UNESCO records construction beginning in 1213 and continuing over decades at Palampet's Rudreshwara Temple. Its sandstone structure carries carved granite and dolerite details, while lightweight porous bricks reduced the roof's weight. The bracket figures preserve aspects of Kakatiya dance and artistic culture. The popular phrase floating bricks describes a material property, not an invitation to remove, wet or test any piece of a protected living temple.\", \"url\": \"https://whc.unesco.org/en/list/1570/\"}], \"bhadrachalam\": [{\"title\": \"Bhadrachalam: Ramadasu and living devotion\", \"kind\": \"Temple-recorded devotional history; sacred stories labelled\", \"text\": \"Bhadrachalam's temple account links its devotional history with Kancherla Gopanna, remembered as Bhakta Ramadasu, and with songs and festivals dedicated to Rama and Seetha. Stories of Bhadra's penance and divine intervention belong to sacred tradition rather than proof that every narrated event occurred. The continuing worship and musical memory are important in their own right. A historical or devotional account is not a current ritual ticket, darshan promise or permission to enter the Godavari.\", \"url\": \"https://bhadradritemple.telangana.gov.in/about_us/\"}], \"yadagirigutta\": [{\"title\": \"Yadadri: sacred tradition and a modern rebuilt complex\", \"kind\": \"Devotional origin tradition, separate from documented modern work\", \"text\": \"The district account tells of sage Yadarshi and Narasimha's manifestations as the sacred origin of Yadagirigutta. These are matters of belief, not a dated archaeological building record. Major rebuilding produced the modern temple complex inaugurated in 2022, so an older photograph can show a very different setting. The deity's continuing worship, the historical tradition and the age of today's visible buildings should not be treated as the same thing.\", \"url\": \"https://yadadri.telangana.gov.in/tourist-place/yadagirigutta/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"mamallapuram\": [{\"title\": \"Mamallapuram: different ways of building in stone\", \"kind\": \"UNESCO-documented Pallava monument history\", \"text\": \"UNESCO places the Mahabalipuram monument group in the Pallava period of the seventh and eighth centuries. Its works use different methods: caves were cut into rock, rathas shaped from individual rock masses, and the Shore Temple assembled as a structural temple. A ratha's epic name does not show that the Pandavas commissioned it, and the great relief has more than one narrative reading. These works belong to a defined protected group, not every attraction in the modern town.\", \"url\": \"https://whc.unesco.org/en/list/249/\"}], \"kanchipuram\": [{\"title\": \"Kailasanathar: Pallava stone, murals and continuing worship\", \"kind\": \"Documented Pallava heritage; building phases kept distinct\", \"text\": \"Incredible India places Kailasanathar's foundation around 700 CE under Narasimhavarman II, also called Rajasimha, with additions by his son. Granite foundations and a sandstone superstructure helped shape its architectural form. Surviving inscriptions and mural traces preserve another part of its history. Kanchipuram's temples were not all built by one ruler or in one century, and a visitor should not touch fragile painted or carved surfaces to examine them.\", \"url\": \"https://www.incredibleindia.gov.in/en/tamil-nadu/kanchipuram/kailasanatha-temple\"}], \"chidambaram\": [{\"title\": \"Chidambaram: the dancing Shiva and a layered temple\", \"kind\": \"Art history and living devotion, not scientific claims\", \"text\": \"Nataraja is Shiva in his dancing form, at the heart of Chidambaram's devotional identity. Historical accounts describe major Chola patronage and later building, repair and expansion rather than a complex completed at one single moment. The gateway towers, halls and sacred chamber belong to this layered history. Interpretations of cosmic dance and sacred space are religious and artistic traditions; they do not establish claims about a magnetic equator, anatomy or physical science.\", \"url\": \"https://www.worldhistory.org/Chidambaram/\"}], \"tiruchirappalli\": [{\"title\": \"Rockfort: an old rock with many later stories\", \"kind\": \"Documented layered temple architecture; geology not a building date\", \"text\": \"Tamil Nadu Tourism describes Pallava rock-cut work and later contributions associated with Vijayanagara and the Madurai Nayaks at Tiruchirappalli's Rockfort. The age of the natural rock is different from the age of any shrine built on or cut into it. Ucchi Pillaiyar and Thayumanaswamy are living places of worship within this stepped landscape, not one unchanged building by one founder. Sacred origin stories remain matters of belief, and the skyline view does not make the climb suitable for everyone.\", \"url\": \"https://www.tamilnadutourism.tn.gov.in/destinations/tiruchirappalli-rockfort-temple\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"thiruvananthapuram\": [{\"title\": \"Napier Museum: an institution older than its building\", \"kind\": \"Museum-recorded institutional and architectural history\", \"text\": \"The museum's own history distinguishes its beginnings in the 1850s and public opening in 1857 from the later building opened in 1880. Robert Fellowes Chisholm designed that replacement using Kerala architectural ideas alongside other influences. The collection's history is therefore not the same as the age of today's building. Historic ivory and other fragile exhibits can be studied as museum objects, not treated as a model for buying wildlife products or handling protected material.\", \"url\": \"https://www.napiermuseum.org/history\"}], \"varkala\": [{\"title\": \"Sivagiri: pilgrimage as learning and reform\", \"kind\": \"Documented reform history; sacred associations kept separate\", \"text\": \"Kerala Tourism records Sree Narayana Guru moving his headquarters to Sivagiri in 1904. Its account describes education and the widening of spiritual learning beyond caste barriers as central to his work there. Sivagiri's importance is therefore more than a coastal viewpoint: it is tied to social reform, learning and continuing religious life. Sacred stories attached to Varkala's temples or bathing places are matters of belief, not proof of medical cures or safe entry into the sea.\", \"url\": \"https://www.keralatourism.org/sreenarayanaguru/sivagiri-pilgrimage/concept\"}], \"kozhikode\": [{\"title\": \"Beypore: a waterfront shaped by Uru builders\", \"kind\": \"Documented maritime craft tradition; working access not assumed\", \"text\": \"Kerala Tourism describes Beypore's long maritime links and the building of large wooden Uru vessels for trade across the Indian Ocean. The craft depends on timber work, judgement and skills passed between builders, rather than a monument finished at one single date. An active yard remains a workplace with its own safety and permission rules. Seeing the river-mouth landscape does not entitle a visitor to enter a yard, board a boat or walk onto port infrastructure.\", \"url\": \"https://www.keralatourism.org/destination/beypore/318/\"}], \"thrissur\": [{\"title\": \"Vadakkumnathan: conservation is part of its history\", \"kind\": \"Documented conservation work; award not World Heritage listing\", \"text\": \"Kerala Tourism's 2016 account describes more than a decade of careful work on Vadakkumnathan's woodwork, murals and other architectural fabric, using traditional methods while respecting ritual requirements. The project received a UNESCO Asia-Pacific heritage conservation Award of Excellence in 2015. That is recognition for conservation, not inscription on the UNESCO World Heritage List. Its continuing worship, craftsmanship and repair history should not be reduced to a single unsupported founding date.\", \"url\": \"https://www.keralatourism.org/kerala-article/2016/vadakkumnathan-temple-thrissur/614\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){","  Object.assign(MONUMENT_STORIES, {\"bishnupur\": [{\"title\": \"Rasmancha and Jorbangla: local forms in brick and laterite\", \"kind\": \"Documented temple architecture; UNESCO tentative scope\", \"text\": \"The UNESCO Tentative List account dates Rasmancha to 1600 and Jorbangla to 1655. Rasmancha uses a pyramidal roof over a laterite platform, while Jorbangla joins two hut-like roof forms into a distinctive temple composition. Terracotta panels connect built form with religious and everyday stories. These are records of Malla-period craft, not evidence that epic figures themselves built the monuments. Tentative listing is a proposal stage, not inscription on the World Heritage List.\", \"url\": \"https://whc.unesco.org/en/tentativelists/1087/\"}], \"murshidabad\": [{\"title\": \"Hazarduari: a later palace in a much older political landscape\", \"kind\": \"District-documented nineteenth-century palace history\", \"text\": \"The Murshidabad district account describes Hazarduari as a nineteenth-century palace designed by Duncan Macleod under Nawab Nazim Humayun Jah. Its grand facade belongs to that later phase, not automatically to earlier rulers or events commonly associated with Bengal's nawabi history. Today its museum setting gives visitors another layer of interpretation. A palace name, a photograph and a local story should not be treated as proof that every object or episode belongs to one original building campaign.\", \"url\": \"https://murshidabad.gov.in/tourist-place/hajarduari-palace/\"}], \"santiniketan\": [{\"title\": \"Santiniketan: education, nature and a wider human community\", \"kind\": \"UNESCO-documented educational and artistic heritage\", \"text\": \"UNESCO links Santiniketan to Rabindranath Tagore's residential school established in 1901 and the world-university vision of Visva-Bharati in 1921. Learning in relation to nature, music and the arts helped shape its buildings and open spaces. The inscribed landscape represents a specific educational and artistic experiment, not every modern business around Bolpur. A living university is also a place of work and study, so heritage status does not give visitors unrestricted access to classes, studios or archives.\", \"url\": \"https://whc.unesco.org/en/list/1375/\"}], \"kalimpong\": [{\"title\": \"Durpin: a monastery above a working hill town\", \"kind\": \"District-recorded modern monastery history and living worship\", \"text\": \"Kalimpong district records the consecration of Zang Dhok Palri monastery by the Dalai Lama in 1976 and its association with the Kangyur and other sacred texts. Its ridge setting is part of its appeal, but the building is a living place of religious practice rather than a viewpoint platform alone. Sacred books, prayer rooms and ceremonies have their own custodians and rules. A photograph of the exterior does not promise access to texts, interiors or a clear Himalayan panorama.\", \"url\": \"https://kalimpong.gov.in/tourist-place/durpin-dara/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"ayodhya\": [{\"title\": \"Kanak Bhawan: sacred tradition and a later temple\", \"kind\": \"Faith tradition separated from later building history\", \"text\": \"The Ayodhya district account presents the story of Kaikeyi gifting a palace to Sita as belief. It separately records rebuilding or renovation by Vrish Bhanu Kunwari. These are different kinds of accounts: a sacred story explains devotional meaning, while a later building campaign concerns the structure visitors see. The temple remains a place of worship dedicated to Rama and Sita. A heritage photograph cannot establish that every Ramayana episode occurred in the present building, or give visitors unrestricted access to its sanctum.\", \"url\": \"https://ayodhya.nic.in/tourist-place/kanak-bhawan/\"}], \"prayagraj\": [{\"title\": \"Khusro Bagh: a Mughal family remembered in stone\", \"kind\": \"District-documented seventeenth-century tomb architecture\", \"text\": \"Prayagraj district describes Khusro Bagh as a walled garden of seventeenth-century Mughal tombs. Its account connects separate monuments with Prince Khusro, his mother Shah Begum and his sister Nesa Begum, noting that her tomb remains empty. A funerary building can therefore carry family memory without containing the burial a visitor might assume. Looking at the garden, domes and carved surfaces is an encounter with layered patronage and remembrance, not permission to climb or touch protected masonry.\", \"url\": \"https://prayagraj.nic.in/places-of-interest/\"}], \"sarnath\": [{\"title\": \"The deer park and the first teaching\", \"kind\": \"Buddhist sacred tradition in district visitor history\", \"text\": \"Varanasi district identifies Sarnath with the deer park where Gautama Buddha first taught the Dhamma and the early Sangha took shape. This is its meaning within Buddhist sacred history. The excavated remains, museum objects and later living temples let visitors encounter different layers of that memory, rather than one unchanged building from the time of the teaching. Respect for prayer and archaeology goes together: neither sacred association nor a museum visit gives access to every shrine, room or protected surface.\", \"url\": \"https://varanasi.nic.in/tourist-place/sarnath/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"mathura\": [{\"title\": \"Mathura Museum: reading an ancient city through sculpture\", \"kind\": \"Documented museum history and archaeological collections\", \"text\": \"Incredible India dates the Government Museum's establishment to 1874 under F. S. Growse and describes its Kushan- and Gupta-period sculpture collections. These objects offer one route into the city's long artistic history, alongside its living sacred traditions. A sculpture's period, a museum's foundation and the age claimed for a holy place are different kinds of dates. Gallery objects can be studied without assuming that every devotional story is a literal account of the present buildings, or that every collection item is on view today.\", \"url\": \"https://www.incredibleindia.gov.in/en/uttar-pradesh/mathura/government-museum\"}], \"vrindavan\": [{\"title\": \"Banke Bihari: a devotional image and its tradition\", \"kind\": \"District-recorded worship tradition; sacred belief distinguished\", \"text\": \"Mathura district links Banke Bihari worship with Swami Haridas and Nidhivan, and describes the image of Krishna in a three-bent or tribhanga posture. The name and form help explain how devotees encounter Krishna in this tradition. This is a living religious inheritance, not proof that the current temple fabric is unchanged from the era of the sacred narratives. Respect for worship also means following present entry, crowd, photography and grove-closure rules rather than treating a story as visitor permission.\", \"url\": \"https://mathura.nic.in/tourist-place/shri-banke-bihari/\"}], \"fatehpursikri\": [{\"title\": \"A planned capital that remained after the court moved\", \"kind\": \"UNESCO-documented Mughal urban and architectural history\", \"text\": \"UNESCO describes Fatehpur Sikri as Akbar's planned capital, with administrative, residential and religious buildings constructed in the later sixteenth century. Its account records the move of the capital to Lahore in 1585, after which Mughal emperors still made temporary visits. The surviving ensemble is therefore more than a simple story of a city suddenly emptied forever. Palace spaces, Jama Masjid and Salim Chishti's shrine preserve different courtly and religious functions, while their present visitor and worship rules remain distinct.\", \"url\": \"https://whc.unesco.org/en/list/255/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"mountabu\": [{\"title\": \"Dilwara: marble craft within living worship\", \"kind\": \"Tourism-documented medieval Jain architecture\", \"text\": \"Rajasthan Tourism places Dilwara's Jain temple complex between the eleventh and thirteenth centuries and describes five temple structures carved in white marble. Doorways, ceilings and interior carving reflect sustained craft and patronage, rather than one simple legend of instant construction. These remain sacred spaces with custodians. A photograph of marble detail, or the architectural fame of the complex, does not establish permission to photograph interiors, touch carvings or enter every shrine.\", \"url\": \"https://tourism.rajasthan.gov.in/mount-abu.html\"}], \"chittorgarh\": [{\"title\": \"A fort landscape of water, worship and political power\", \"kind\": \"UNESCO-documented serial fort heritage\", \"text\": \"UNESCO's Hill Forts of Rajasthan account includes Chittorgarh within a six-fort serial property. Its description connects fortifications with palaces, towns, temples, trade and water-harvesting systems, rather than treating a fort as a military wall alone. Some sacred and urban spaces continued in use. The present ruins therefore hold many layers of work, worship and political change. Later heroic stories can shape remembrance without proving every named room or episode, and heritage status does not make reservoirs or ruins safe to enter.\", \"url\": \"https://whc.unesco.org/en/list/247/\"}], \"ranakpur\": [{\"title\": \"Ranakpur: patronage and a sacred dream\", \"kind\": \"Fifteenth-century temple history with dream legend labelled\", \"text\": \"Rajasthan Tourism associates the Ranakpur temple with the patron Dhanna Shah and Rana Kumbha, and places the main Jain temple in the fifteenth century. It separately recounts a dream of a celestial vehicle as legend explaining the patron's vision. The historical patronage and the sacred dream should not be treated as the same kind of evidence. The Chaumukha shrine is dedicated to Adinath. Today its marble halls belong to living worship, so architectural interest gives no automatic right to every ritual, shrine or photograph.\", \"url\": \"https://www.tourism.rajasthan.gov.in/content/rajasthan-tourism/en/tourist-destinations/ranakpur-temple.html\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"gokarna\": [{\"title\": \"The Atmalinga: a sacred Gokarna tradition\", \"kind\": \"Hindu sacred legend, not independently verified history\", \"text\": \"Karnataka Tourism recounts the Hindu tradition that Ravana received Shiva's Atmalinga and that Ganesha, disguised as a cowherd, placed it on the ground at Gokarna, where it could no longer be moved. This is a sacred account of the town's religious importance, not documentary proof of a dated event. Mahabaleshwar remains a place of worship rather than a story set. Its current custodians determine dress, eligibility for shrine areas, rituals and photography; hearing the legend gives no automatic admission to every space.\", \"url\": \"https://karnatakatourism.org/en/destinations/gokarna\"}], \"chikkamagaluru\": [{\"title\": \"Baba Budan, coffee seeds and a growing landscape\", \"kind\": \"Coffee-origin tradition distinguished from later plantation history\", \"text\": \"The Coffee Board of India retells the story of the holy saint Baba Budan bringing seven Mocha seeds and planting them in the hills that bear his name. It presents the beginnings through a legendary figure; the exact seed count and journey are not treated here as independently verified evidence. The Board separately describes coffee spreading slowly through garden plantings before commercial plantations developed in the eighteenth century. Today's coffee landscape is the result of generations of growing and trade, not only one celebrated journey. Estates remain working and often private places, so a coffee purchase or photograph is not permission to enter or pick.\", \"url\": \"https://coffeeboard.gov.in/aboutus.aspx\"}], \"belurhalebidu\": [{\"title\": \"Hoysala stonework and the artists who signed it\", \"kind\": \"UNESCO-documented twelfth-to-thirteenth-century architecture\", \"text\": \"UNESCO identifies Channakeshava at Belur, Hoysalesvara at Halebidu and Keshava at Somanathapura as the three components of the Sacred Ensembles of the Hoysalas. Their platforms, star-like plans, layered friezes and story galleries combined earlier and contemporary architectural ideas. UNESCO also draws attention to the many artists' signatures, evidence of their standing and agency rather than anonymous decoration alone. The Sala tiger-killing motif is described as legend, not a witnessed historical event. Belur has continued worship since its inception in 1117, while the three component sites have different uses and access conditions. A UNESCO listing is not a single ticket or unrestricted ritual/photo permit.\", \"url\": \"https://whc.unesco.org/en/list/1670/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"udupi\": [{\"title\": \"Madhvacharya and the sea-rescue tradition\", \"kind\": \"Matha foundation history with sacred voyage narrative labelled\", \"text\": \"Sri Pejavara Matha associates Udupi Krishna Matha with Madhvacharya in the thirteenth century. Its account also tells of a ship in danger near Malpe, the saint helping it reach safety, and Krishna and Balarama deities reaching the coast with the grateful sailors. The rescue and deity-journey are retold here as a sacred institutional tradition, not independently verified details of a maritime incident. The living matha and neighbouring shrines have their own current rules. Hearing this story does not promise ritual admission, a particular meal, or access to every shrine space.\", \"url\": \"https://pejavaramatha.in/srikrishna-matha/\"}], \"murudeshwar\": [{\"title\": \"Atmalinga tradition and a modern coastal monument\", \"kind\": \"Sacred legend distinguished from modern monumental patronage\", \"text\": \"Karnataka Tourism recounts the Hindu legend connecting Murudeshwara with Ravana, Ganesha and the covering of Shiva's Atmalinga. That account explains sacred geography, not a verified dated event. The large statue and Raja Gopuram that shape the present skyline are a separate modern layer: the R. N. Shetty group's account credits his funding for the temple complex's monumental additions. Ancient religious significance and modern construction should not be collapsed into one building date. Neither story nor statue photograph gives automatic shrine, tower, lift or offshore-activity access.\", \"url\": \"https://karnatakatourism.org/en/destinations/murudeshwara/\"}], \"somanathapura\": [{\"title\": \"Three shrines, many carved stories\", \"kind\": \"UNESCO-documented Hoysala heritage with tourism patronage context\", \"text\": \"UNESCO places the Keshava temple at Somanathapura alongside Belur and Halebidu within the Sacred Ensembles of the Hoysalas, whose temples date from the twelfth and thirteenth centuries. Karnataka Tourism associates this temple with the commander Somanatha Dandanayaka under Narasimha III. Its three-shrine layout, shaped platform and carved epic narratives show how architecture and sculpture worked together. A religious scene carved in stone is evidence of artistic and devotional storytelling, not proof that the depicted event happened on this site. Unlike Belur's continuing worship, UNESCO records a loss of religious activities here; this does not remove protected-monument visitor rules.\", \"url\": \"https://whc.unesco.org/en/list/1670/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"kolhapur\": [{\"title\": \"Ambabai devotion, royal heritage and different city landmarks\", \"kind\": \"Documented city heritage with sacred significance attributed\", \"text\": \"Kolhapur district's official account places Ambabai/Mahalaxmi devotion at the centre of the city's identity and describes its Shaktipeeth importance as part of Hindu mythology. The same district source lists New Palace and Bhavani Mandap separately. They should not be collapsed into one monument simply because both belong to the city's royal heritage. A palace exterior, a temple ritual and a museum collection tell different kinds of stories. Sacred status does not establish a particular building date or automatic access to a sanctum, royal room or gallery.\", \"url\": \"https://kolhapur.gov.in/en/places-of-interest/\"}], \"mahabaleshwar\": [{\"title\": \"Pratapgad: a fort with a strategic purpose\", \"kind\": \"District-documented seventeenth-century Maratha history\", \"text\": \"Satara district's official account dates Pratapgad's construction under Shivaji Maharaj to 1656 and places the confrontation with Afzal Khan there in November 1659. The fort belonged to a wider landscape of routes, passes and political control, rather than being only a dramatic viewpoint. Today's visit involves separate hill-road travel from Mahabaleshwar and uneven fortified spaces. Retellings may add dialogue and heroic detail that this short account does not claim to verify; historical importance is not permission to climb ramparts or enter closed paths.\", \"url\": \"https://www.satara.gov.in/en/tourist-place/pratapgad/\"}], \"lonavala\": [{\"title\": \"Bhaja: prayer, residence and rock-cut space\", \"kind\": \"Tourism-documented early Buddhist architectural heritage\", \"text\": \"Maharashtra Tourism describes Bhaja near Lonavala as an early Buddhist rock-cut complex, with a chaitya prayer hall and stupa alongside viharas used for monastic life. These different spaces show that the site served a community's worship and residence, rather than being a fort or a single freestanding temple. Carved narratives belong to artistic and religious storytelling, not proof that each depicted event occurred at Bhaja. Karla is another separate cave visit, and nearby living Ekvira worship has its own rules. Monument interest does not grant unrestricted photography, touching or access to closed areas.\", \"url\": \"https://maharashtratourism.gov.in/cave/bhaja/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"vadodara\": [{\"title\": \"A nineteenth-century palace that is still a residence\", \"kind\": \"Tourism-documented Gaekwad patronage and living residence\", \"text\": \"Gujarat Tourism dates Lukshmi Vilas Palace to 1890 under Maharaja Sayajirao Gaekwad III and identifies Major Charles Mant as its main architect. The palace belongs to a nineteenth-century royal landscape of collections, gardens and other buildings, rather than an undifferentiated ancient monument. The same source says it remains the royal family's residence. Public curiosity therefore does not grant entry to every room, garden, sports facility or associated museum; present visitor boundaries and photography rules still apply.\", \"url\": \"https://www.gujarattourism.com/central-zone/vadodara/laxmi-vilas-palace.html\"}], \"patan\": [{\"title\": \"Rani-ki-Vav: water storage shaped like an inverted temple\", \"kind\": \"UNESCO-documented eleventh-century water architecture\", \"text\": \"UNESCO describes Rani-ki-Vav as an eleventh-century memorial and a functional water-resource structure designed like an inverted temple. Its descending stairs, pavilions, tank and well combine engineering with religious, mythological and secular sculpture. These images celebrate water and tell cultural stories; they are not evidence that every depicted event took place at Patan. UNESCO also records that changes to the river and groundwater ended the well's original function. Today it is a protected monument, not a working public well, bathing tank or unrestricted underground passage.\", \"url\": \"https://whc.unesco.org/en/list/922/\"}], \"modhera\": [{\"title\": \"Sun worship, stone spaces and a stepped kund\", \"kind\": \"Eleventh-century architectural history; UNESCO Tentative List status\", \"text\": \"Gujarat Tourism associates Modhera's Sun Temple with Bhima I of the Chaulukya dynasty in the eleventh century. The temple, assembly space and Surya Kund connect solar devotion with an architectural sequence of gathering, carving and water. Stories and symbolic imagery express worship, not proof of a promised light effect on any visitor's chosen date. UNESCO's current record places the temple and adjoining monuments on India's Tentative List, which is a proposal stage rather than World Heritage inscription. Historical significance gives no automatic access to closed stonework, water or a performance.\", \"url\": \"https://whc.unesco.org/en/tentativelists/6627/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"jammu\": [{\"title\": \"Raghunath Temple and Dogra patronage\", \"kind\": \"Nineteenth-century royal temple history; exact dates differ between official summaries\", \"text\": \"Jammu district and tourism sources connect the Raghunath temple complex with Maharaja Gulab Singh and Maharaja Ranbir Singh in the nineteenth century. Their short accounts give differing construction dates, so this guide does not choose one exact year. Multiple shrines and a Sanskrit manuscript collection show how worship, scholarship and royal patronage share the complex. Accounts of Rama and other deities are religious tradition; they are distinct from the recorded building history. Current security, collection and photography rules determine what visitors may see.\", \"url\": \"https://jammu.nic.in/tourist-place/raghunath-temple-jammu/\"}], \"katra\": [{\"title\": \"A town base and three sacred Pindies\", \"kind\": \"Living Hindu belief and a regulated mountain pilgrimage\", \"text\": \"Jammu Tourism describes Katra as the base for the Shri Mata Vaishno Devi pilgrimage and the shrine darshan as three natural rock formations called Pindies. Devotees understand these forms through their faith; this guide does not turn that belief into geological proof of a divine event. The Shrine Board separately regulates the journey through individual registration and access cards. A story, town visit or hotel stay is not permission to bypass registration, queues, route closures or current shrine rules.\", \"url\": \"https://maavaishnodevi.org/blog/yatra-registration\"}], \"kurukshetra\": [{\"title\": \"Sacred tanks and the memory of the Gita\", \"kind\": \"Hindu sacred geography and epic tradition, not a dated archaeological verdict\", \"text\": \"Haryana Tourism describes Kurukshetra through its association with the Mahabharata and the Bhagavad Gita, with Jyotisar revered as the site of Krishna's teaching to Arjuna. Brahma Sarovar and Sannihit Sarovar belong to this wider landscape of pilgrimage and sacred-water beliefs. These traditions explain why visitors come; they do not establish a scientific date or material proof for every epic episode. The wider 48-kos pilgrimage circuit extends beyond one town walk. Present shrine, museum and water-edge rules remain separate from religious narratives.\", \"url\": \"https://haryanatourism.gov.in/destinations/kurukshetra/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}

{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"deoghar\": [{\"title\": \"Naulakha: a name linked to a gift\", \"kind\": \"District-recorded temple patronage; religious practice remains separate\", \"text\": \"Deoghar district describes Naulakha Temple as a Radha-Krishna shrine funded by Rani Charushila of Kolkata's Pathuria Ghat family. Its name is linked in that account to a contribution of nine lakh rupees. This is a historical naming explanation, not a present admission fee or a modern valuation. The account connects the patron's loss and her meeting with Balananda Brahmachari to the building of the shrine. Present worship, photography and visitor areas remain subject to the custodian's rules.\", \"url\": \"https://deoghar.nic.in/tourist-place/naulakhatemple/\"}], \"ranchi\": [{\"title\": \"A seventeenth-century Jagannath shrine on the plateau\", \"kind\": \"Tourism-documented royal patronage and living worship\", \"text\": \"Jharkhand Tourism dates the Jagannath Mandir at Dhurwa to 1691 and attributes it to Barkagarh ruler Thakur Ani Nath Shahdeo. The hilltop temple brings the worship of Jagannath into Ranchi's plateau landscape; it is not the same building as Puri's temple. Rath Yatra connects the shrine with a living annual tradition, but an account of that tradition gives no guaranteed current procession date, route, ritual access or photograph permission. Those details require the institution's present directions.\", \"url\": \"https://tourism.jharkhand.gov.in/destination-map/94\"}], \"jamshedpur\": [{\"title\": \"Jubilee Park and the making of a company city\", \"kind\": \"Officially documented twentieth-century civic landscape\", \"text\": \"East Singhbhum district describes planning for a central park beginning in 1937, with the project resumed in 1955 around the company jubilee. The state forest department records Jubilee Park opening to the public in 1958 as a Tata Steel gift to the town. This is modern civic and landscape history, not an ancient royal garden. The park's relationship with the city's industrial growth does not give visitors factory entry or access to every zoo, lake or event area. Current rules remain separate.\", \"url\": \"https://jamshedpur.nic.in/tourist-places-2/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}
{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"raipur\": [{\"title\": \"Purkhauti Muktangan: a modern cultural landscape\", \"kind\": \"District-documented twenty-first-century cultural display\", \"text\": \"Raipur district records Purkhauti Muktangan as inaugurated in November 2006 by former President A.P.J. Abdul Kalam. Its figures and folk-art displays present selected aspects of Chhattisgarh's cultural life in a curated setting. They are representations, not proof that every community shares one costume, ritual or way of life. A cultural-park visit gives no invitation to enter private homes or photograph people without consent. Current opening, tickets and visitor routes remain separate from the story of the display.\", \"url\": \"https://raipur.gov.in/en/tourist-place/muktangan/\"}], \"jagdalpur\": [{\"title\": \"Bastar Palace and living royal heritage\", \"kind\": \"Historic palace landscape with present-day access limits\", \"text\": \"Incredible India presents Bastar Palace in Jagdalpur as part of the region's royal and cultural heritage. It belongs to a living town and cultural landscape, not an abandoned stage on which every room or ritual is open to visitors. Stories, architecture and local observances help explain its meaning, but do not establish a right of entry or photography. Check the current custodian's public visitor areas, keep private spaces private and ask permission before photographing people or ceremonies.\", \"url\": \"https://www.incredibleindia.gov.in/en/chhattisgarh/jagdalpur/bastar-palace\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}
{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"pachmarhi\": [{\"title\": \"Pandav Caves: tradition and what visitors see\", \"kind\": \"Traditional name for rock-cut dwellings, with limits on dating\", \"text\": \"Narmadapuram district describes the Pandav Caves at Pachmarhi as a group of five dwellings cut out of sandstone on a hill. The name links them to the Pandavas of the Mahabharata, which is local tradition and belief, not evidence that the epic figures lived there. This guide gives no construction date because the official page used here does not give one. Hill steps, rock surfaces and custodian rules matter, and cave interiors may be restricted.\", \"url\": \"https://narmadapuram.nic.in/en/tourist-place/pachmarhi/\"}], \"bhedaghat\": [{\"title\": \"Chausath Yogini Temple above the Narmada\", \"kind\": \"Hilltop shrine with medieval origins\", \"text\": \"Madhya Pradesh Tourism describes the 10th-century Chausath Yogini Temple as a hilltop shrine dedicated to Goddess Durga, with a circular layout and carved stone figures, overlooking the Narmada at Bhedaghat. It is presented as an ancient temple of the Yogini tradition, not a modern viewpoint. Visitors should follow the custodian's rules on steps, dress, photography and worship, and check current access before the climb.\", \"url\": \"https://www.mptourism.com/destination-bhedaghat.php\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}
{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"nagpur\": [{\"title\": \"Deekshabhoomi: where Ambedkar embraced Buddhism\", \"kind\": \"Modern memorial and pilgrimage site\", \"text\": \"The Nagpur district page says Deekshabhoomi marks the place where B. R. Ambedkar converted to Buddhism on 14 October 1956 with a large number of followers, and calls it a pilgrimage centre with a great stupa. The Maharashtra tourism heritage page describes it as the largest stupa in India, modelled on Sanchi. Crowds peak around the anniversary and Ashok Vijaya Dashmi, so check current rules and timings. This is a living memorial, so dress and behave respectfully.\", \"url\": \"https://nagpur.gov.in/historical-places/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}
{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"spiti\": [{\"title\": \"Key (Kye) Monastery above Kaza\", \"kind\": \"Large Buddhist monastery\", \"text\": \"The Lahaul and Spiti district page describes Kye (Key) Monastery as the largest in the valley, on a conical hill about 13,500 ft above Kaza, a heap of low rooms and narrow corridors with murals, thankas and manuscripts. It mentions the Kalachakra ceremony of August 2000 led by the Dalai Lama and says the gompa is 12 km by road or an 8.5 km trek from Kaza. The page gives no founding date, so none is given here. It is a working monastery, so follow its rules on entry, dress and photography.\", \"url\": \"https://hplahaulspiti.nic.in/tourist-place/key-monastery/\"}], \"pandharpur\": [{\"title\": \"Shri Vitthal-Rukmini Mandir and the Pundalik legend\", \"kind\": \"Temple history with a tradition kept separate\", \"text\": \"The Maharashtra Tourism page says the temple's origins go back to the 12th century, believed to be under Hoysala king Vishnuvardhana, and that it has been renovated many times. The Solapur district page says the Vitthal temple was renovated in 1195 A.D. The story of Pundalik, who offered Krishna a brick to stand on while he served his parents, is tradition and belief, not dated history. Check the temple committee for current darshan rules.\", \"url\": \"https://maharashtratourism.gov.in/temple/pandharpur/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}
{let s=fs.readFileSync("private-assets/app.js","utf8");s=s.replace("  function renderMonumentStories(d){", "Object.assign(MONUMENT_STORIES, {\"kasol\": [{\"title\": \"Manikaran: hot springs and a shared pilgrimage\", \"kind\": \"Pilgrimage town with a legend kept separate\", \"text\": \"The Kullu district page describes Manikaran, at about 1,829 m and 40 km from Kullu, as famous for its hot springs, and as a favourite pilgrim stop for Hindus and Sikhs because of the Raghunath temple and the gurudwara. It says an ancient legend links the place to Shiva and Parvati. That is tradition and belief, not dated history, and the page gives no founding date. The springs are very hot, so follow local rules and keep clear of the water edge.\", \"url\": \"https://hpkullu.nic.in/tourist-place/manikaran/\"}]});\n"+"  function renderMonumentStories(d){");fs.writeFileSync("private-assets/app.js",s);}
